__NUXT_JSONP__("/sp/stay", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{details:{slug:"sp",pageTitle:"Alojamiento | Mentor Language Institute",pageDescription:b,title:"Alojamiento",subtitle:[b],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"Los estudiantes pueden elegir alojamiento en casa de familias anfitrionas o en dormitorios.",types:[{title:"Dormitorio",description:["Hay 40 habitaciones en el dormitorio. Habrá muchas oportunidades para comunicarse con otros estudiantes internacionales. \u003Cbr \u002F\u003E Te recomendamos que te alojes en un dormitorio si tenes un presupuesto ajustado."],lists:["Habitación: privada (individual), compartida (2 personas) o cuádruple (4 personas)","Comida: Sin comidas [hay disponible una cocina completamente equipada]","Privacidad: hay más privacidad en los dormitorios que en una casa de familia, sin embargo, hay algunas reglas de dormitorio.","Conmutar a la escuela: aproximadamente 20 minutos a pie o en autobús."],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"Precios dormitorio",table:{tableMaxCol:4,title:"Cuota de acomodación* : $200\u003Cbr \u002F\u003E Si es menor de 18 años, el alquiler será aproximadamente un 10% superior al precio de una persona mayor de 18 años",thead:[c,d,"Compartido (2 semanas)","Quádruple (4 personas)"],tbody:[[e,a,a,a],[f,"$550","$410",a],[g,"$1,100","$820","$600"],[h,"$1,650","$1,230","$900"],[i,"$2,200","$1,640","$1,200"],[j,"$4,160","$2,960","$2,160"],[k,"$6,240","$4,440","$3,240"]]},notes:["*La cuota de acomodación se paga por única vez. No es reembolsable.\u003Cbr \u002F\u003E**El depósito de seguridad sera reembolsado despues de que los alumnos se hayan ido de su acomodación."]}]},{title:"Homestay",description:["Los estudiantes que eligen vivir con una familia anfitriona están buscando un lugar seguro, acogedor,y una atmósfera cómoda en la que pueden practicar sus habilidades de inglés. También es una oportunidad para aprender sobre las costumbres, tradiciones y valores familiares estadounidenses."],lists:["Habitación: privada (individual)","Comida: 2 comidas al día (desayuno y cena)","Privacidad: hay algunas reglas de la casa que dependen de la familia anfitriona.","Conmutar: 30-45 minutos promedio en autobús"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"Precios Homestay",table:{tableMaxCol:3,title:"Cuota de acomodación* : $300\u003Cbr \u002F\u003E Si es menor de 18 años, el alquiler será aproximadamente un 10% superior al precio de una persona mayor de 18 años",thead:[c,d,"Compartido***"],tbody:[[e,a,a],[f,"$436","$384"],[g,"$872","$768"],[h,"$1,308","$1,152"],[i,"$1,744","$1,536"],[j,"$3,160","$2,904"],[k,"$4,740","$4,356"]]},notes:["*La cuota de acomodación se paga por única vez. No es reembolsable.\u003Cbr \u002F\u003E**El depósito de seguridad sera reembolsado despues de que los alumnos se hayan ido de su acomodación.\u003Cbr \u002F\u003E***Si solicitas Homestay (cuarto compartido) , debes aplicar con otra persona."]}]}],comments:{title:"Comentarios de nuestro personal",description:["No es fácil encontrar un lugar donde alojarse cuando llegas por primera vez a los EE. UU. especialmente para estudiantes internacionales que no tienen un Número de Seguridad Social (SSN) e historial de crédito.\u003Cbr \u002F\u003ELa mayoría de los lugares requieren un SSN y un historial de crédito para alquilar un lugar.\u003Cbr \u002F\u003EPor lo tanto, te recomendamos que te quedes en nuestro alojamiento al menos los primeros meses.","※ Su alojamiento será provisto por U.S. Support Service Inc. u otros agentes."]},dir:"\u002Fstay",path:"\u002Fstay\u002Fsp",extension:".json",createdAt:"2026-10-22T16:31:31.114Z",updatedAt:"2025-05-26T12:06:27.922Z"}}],fetch:{},mutations:void 0}}("$300","MLI trabaja con U.S. Support Services Inc. la cual provee alojamiento a los estudiantes de MLI.","","Privado (Individual)","\u003Cb\u003EDepósito**\u003C\u002Fb\u003E","1 semana","2 semanas","3 semanas","4 semanas","8 semanas","12 semanas")));